import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Главная', () => {
  test('HM-02 «תפילות אחרונות»: время различимо, лимит, «צפה בהכל» #6a86f7e5 @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. Открыть `/home` → блок «תפילות אחרונות».
    await page.goto('/home');
    await expect(page.getByText('תפילות אחרונות', { exact: true })).toBeVisible({ timeout: 20_000 });
    const viewAll = page.getByRole('link', { name: 'צפה בהכל' });
    await expect(viewAll).toBeVisible();
    // Строки вида «<евр. дата> · HH:mm» (или HH:mm:ss) — не больше 3 записей.
    const times = page.getByText(/^[א-ת״׳' ]+ · \d{2}:\d{2}(:\d{2})?$/);
    await expect(times.first()).toBeVisible();
    const count = await times.count();
    expect(count).toBeGreaterThanOrEqual(1);
    expect(count).toBeLessThanOrEqual(3);

    // 2. Нажать «צפה בהכל».
    await viewAll.click();
    await expect(page).toHaveURL(/\/journey\/history$/);
  });
});
